        protected override void setupDefaultResultParams(Dictionary<string, string> dicParams, double userBalance, int index, int counter, string initString)
        {
            base.setupDefaultResultParams(dicParams, userBalance, index, counter,initString);
	    	dicParams["reel_set"] = "0";
	        dicParams["g"] = "{gp:{def_s:\"13,13,13,13,13,13,13,13,13,13,13,13,13,13,13,13,13,13,13,13,13,13,13,13,13\",def_sa:\"13,13,13,13,13\",def_sb:\"13,13,13,13,13\",reel_set:\"42\",s:\"13,13,13,13,13,13,13,13,13,13,13,13,13,13,13,13,13,13,13,13,13,13,13,13,13\",sa:\"13,13,13,13,13\",sb:\"13,13,13,13,13\",sh:\"5\",st:\"rect\",sw:\"5\"}}";
